variables.body:
// Main
if (!row) {
    $ctrl.selectedEntity = null;
    $ctrl.selectedEntityName = null;
    $ctrl.selectedEntityDetails = "";

    if (document.getElementById("details")) document.getElementById("details").innerHTML = null;
    return;
}

$ctrl.selectedEntity = row;
$ctrl.selectedEntityDetails = "";

[
    row.Earnings,
    row.Benefits,
    row.Taxes,
    row.AccrualBalance
].forEach((payComponentsArr) => {
    mapIdsToNames(payComponentsArr);
});

const { workerPayComponents: workerEarnings, positionPayComponents: positionEarnings } = splitByOrigin(row.Earnings);
const { workerPayComponents: workerBenefits, positionPayComponents: positionBenefits } = splitByOrigin(row.Benefits);

$ctrl.payComponents = {
    workerEarnings,
    workerBenefits,
    positionEarnings,
    positionBenefits,
    taxes: [row.Taxes]
}

$ctrl.workerAccrualBalances = [[...row.AccrualBalance]]
$ctrl.workerAccrualBalances.forEach(accrualBalanceArrays => {
    accrualBalanceArrays.forEach(accrualBalance => {
        accrualBalance.Name = accrualBalance.Accrual;

        Object.entries(accrualBalance).forEach(([key, value]) => {
            if (typeof value === "object") accrualBalance[key] = value.Name;
            if (accrualBalance[key] === undefined) delete accrualBalance[key];
        });
    });
});

$ctrl.handlePayComponentTabChange($ctrl.payComponentSelectedTab)
setEntityName();
// End of Main

// Functions
function setEntityName() {
    for (const key in row) {
        if ((row.hasOwnProperty(key) && key.toLowerCase().includes("name")) || ((row.hasOwnProperty(key) && key.toLowerCase().includes("title")))) {
            $ctrl.selectedEntityName = row.FirstName + " " + row.LastName;
            break;
        }
    }
}

function mapIdsToNames(payComponentArr) {
    payComponentArr.forEach((payComponent) => {
        Object.entries(payComponent).forEach(([key, value]) => {
            if (typeof payComponent[key] === "object") {
                if (key.includes("CalculationMethod")) {
                    payComponent[key] = (payComponent[key].Id === 1)
                        ? "FLAT"
                        : "PERCENT";
                }
                if (key.includes("Currency")) {
                    payComponent[key] = $ctrl.currencies.find(currency => currency?.Id === value.Id)?.CurrencyName ?? payComponent[key];
                } else if (key.includes("Accrual")) {
                    payComponent[key] = $ctrl.accruals.find(accrual => accrual?.Id === value.Id)?.Name ?? payComponent[key];
                }
            }
        });
    });
}

function splitByOrigin(payComponentArr) {
    return payComponentArr.reduce((acc, payComponent) => {
        if (payComponent.Origin === "WORKER") {
            acc.workerPayComponents.push(payComponent);
        } else {
            acc.positionPayComponents.push(payComponent);
        }
        return acc;
    }, { workerPayComponents: [], positionPayComponents: [] });
}

const date = new Date(dateString);

const pad = (num, size) => String(num).padStart(size, '0');

const year = date.getUTCFullYear();
const month = pad(date.getUTCMonth() + 1, 2);
const day = pad(date.getUTCDate(), 2);
const hours = pad(date.getUTCHours(), 2);
const minutes = pad(date.getUTCMinutes(), 2);
const seconds = pad(date.getUTCSeconds(), 2);
const milliseconds = pad(date.getUTCMilliseconds(), 3);

return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}.${milliseconds}`;

switch (result) {
    case "OK":
        $ctrl.$notificationManager.show(message, {
            delay: 3500,
            icon: 'check',
            color: 'success',
            dismissible: true,
            animation: 'fade'
        });
        break;

    case "INFO":
        $ctrl.$notificationManager.show(message, {
            delay: 2500,
            icon: 'info-circle',
            color: 'primary',
            dismissible: true,
            animation: 'fade'
        });
        break;

    case "WARNING":
        $ctrl.$notificationManager.show(message, {
            delay: 2500,
            icon: 'exclamation-triangle',
            color: 'warning',
            dismissible: true,
            animation: 'fade'
        });
        break;

    default:
        $ctrl.$notificationManager.show(message, {
            delay: 5000,
            icon: 'exclamation-circle',
            color: 'danger',
            dismissible: true,
            animation: 'fade'
        });
        break;
}

const limit = 1000;
const offset = 0;

return $ctrl.payrollAppApi[endpoint](
    { limit: limit, offset: offset },
    { headers: $ctrl.authCookies.setHeaders() }
)
    .then((result) => result.data[entity])
    .catch((reason) => {
        $ctrl.utils.toast(reason.data.message, reason.data.result);
        throw reason;
    });

const result = {};
for (const key in form) {
    if (form.hasOwnProperty(key)) {
        const titleCaseKey = key.charAt(0).toUpperCase() + key.slice(1);

        if ((/^(is|need|with|can|allow|active|salaried|enabled|final)/i.test(key) || key.toLowerCase() === "employercontribution") && method === "POST") {
            result[titleCaseKey] = form[key] || false;
        } else if (key.includes("Date") && form[key]) {
            result[titleCaseKey] = $ctrl.parseDate(form[key]);
        } else {
            result[titleCaseKey] = form[key];
        }
    }
}
return result;

if (method === "POST") $ctrl.isInserting = true;
if (method === "PUT") $ctrl.isUpdating = true;

$ctrl.payrollAppApi[endpoint](
    {
        body: {
            ...$ctrl.buildRequestBody(form, method),
            ...(method === "PUT" ? { "Id": $ctrl.selectedEntity.Id } : {})
        }
    },
    { headers: $ctrl.authCookies.setHeaders() }
).then(result => {
    $ctrl.toast(`Successfully ${$ctrl.isInserting ? "added" : "edited"} ${entityName}`, result.data.result);
    if ($ctrl.isInserting) $ctrl.setIsAdding();
    if ($ctrl.isUpdating) $ctrl.setIsEditing();
    $ctrl.getAllEntities();
    $ctrl.resetForm(form);
})
    .catch(reason => {
        $ctrl.toast(reason.data.message, reason.data.result);
    })
    .finally(() => {
        if ($ctrl.isInserting) $ctrl.isInserting = false;
        if ($ctrl.isUpdating) $ctrl.isUpdating = false;
    });

const toBeDeletedEntity = $ctrl.selectedEntityName;
let isConfirmed;
$ctrl.isDeleting = true;

await $ctrl.$modal.open("delete-entity-modal", {
    props:
    {
        EntityName: $ctrl.selectedEntityName,
        EntityDetails: $ctrl.selectedEntityDetails
    }
}).then(response => isConfirmed = response.result === "ok");

if (isConfirmed) {
        $ctrl.payrollAppApi[endpoint](
            { id: $ctrl.selectedEntity.Id },
            { headers: $ctrl.authCookies.setHeaders() }
        ).then(result => {
            $ctrl.getAllEntities();
            $ctrl.toast(`Successfully deleted ${toBeDeletedEntity}`, result.data.result);
            $ctrl.isDeleting = false;
        }).catch(reason => {
            $ctrl.toast(reason.data.message, reason.data.result);
            $ctrl.isDeleting = false;
        }).finally(() => {
            $ctrl.isDeleting = false;
        });

} else {
    $ctrl.isDeleting = false;
}

const isProd = $ctrl.$env.current.name === "prod";
const isDev = $ctrl.$env.current.name === "dev";

if ((isProd || isDev) && !$ctrl.$cookies.get("id_token")) {
    window.location.href = "#!/user_login";
    return;
}

const usrIsAdmin = await $ctrl.authService.redirectWorker();
if(!usrIsAdmin) return;

if ((isProd || isDev) && ($ctrl.pageParameters.id === ":id" || !$ctrl.pageParameters.id)) {
    window.location.href = "#!/payroll_processing";
    return;
}

if ($ctrl.isFirstLoad) $ctrl.authCookies.getAuthToken().then(() => $ctrl.isFirstLoad = false);

let userSelectedProceed = true;
if ($ctrl.hasModifiedPayrollRunReview && source === "reload") {
    userSelectedProceed = await $ctrl.$modal.open("confirm-action-modal", {
        title: "Discard Pay Component Overrides?",
        body: "Reloading will discard Pay Component Overrides. Proceed?"
    }).then(res => {
        if (res.result === "ok") return true;
        else return false;
    })
}

if (!userSelectedProceed) return;

// Resets
$ctrl.currentPage = 1;
$ctrl.entityUiStateService.initializationError = null;

$ctrl.selectedEntityName = null;
$ctrl.selectedEntity = null;
$ctrl.selectedEntityDetails = null;

$ctrl.workerPayslip = null;
$ctrl.selectedPayslip = null;
$ctrl.selectedPayslipName = null;
$ctrl.selectedPayslipDetails = null;
$ctrl.isViewingPayslip = null;

$ctrl.filterTarget = null;

$ctrl.activeAssignmentView = null;
$ctrl.selectedPayComponent = null;
$ctrl.originalAssignedToWorkers = null;
$ctrl.assignedToWorkers = null;

if ($ctrl.tableData) $ctrl.tableData.length = 0;
if ($ctrl.filteredTableData) $ctrl.filteredTableData = 0;

// Main
$ctrl.isGettingEntities = true;

// Append Font Awesome link if not already present
if (!document.querySelector('link[href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css"]')) {
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = 'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css';
    document.head.appendChild(link);
}

Promise.all([
    !modifiedPayrollRunReview
        ? $ctrl.payrollAppApi.lonti_app_payroll_service_payroll_run_GetCachedPayrollRunReviewJob(
            {
                id: $ctrl.pageParameters?.id,
                jobId: $ctrl.pageParameters?.jobId,
            },
            { headers: $ctrl.authCookies.setHeaders() }
        ).then(result => result.data)
        : $ctrl.payrollAppApi.lonti_app_payroll_service_payroll_run_InitiateReviewPayrollRun(
            {
                id: $ctrl.pageParameters?.id,
                maskSensitiveWorkerInfo: maskSensitiveWorkerInfo,
                encashAccrualBalances: encashAccrualBalances
            },
            $ctrl.payrollRunReview.PayrollRunReview.Workers.map(worker => {
                return {
                    WorkerId: worker.Id,
                    Earnings: worker.Earnings.map(earning => {
                        return {
                            Id: earning.Id,
                            CustomAmount: earning.CustomAmount
                        }
                    }),
                    Benefits: worker.Benefits.map(benefit => {
                        return {
                            Id: benefit.Id,
                            CustomEmployeeAmount: benefit.CustomEmployeeAmount,
                            CustomEmployerAmount: benefit.CustomEmployerAmount
                        }
                    })
                }
            }),
            { headers: $ctrl.authCookies.setHeaders() }
        ).then(result => result.data),
    $ctrl.getData('lonti_app_payroll_service_currency_SelectAllCurrency', 'currency'),
    $ctrl.getData('lonti_app_payroll_service_accrual_SelectAllAccrual', 'accrual'),
    $ctrl.getData('lonti_app_payroll_service_earning_SelectAllEarning', 'earning'),
    $ctrl.getData('lonti_app_payroll_service_benefit_SelectAllBenefit', 'benefit'),
    $ctrl.getData('lonti_app_payroll_service_company_SelectAllCompany', 'company'),
]).then(results => $ctrl.$timeout(() => {
    const [
        payrollRunReview,
        currencies,
        accruals,
        earnings,
        benefits,
        companies,
    ] = results;

    $ctrl.dataHandlers.setContext($ctrl);

    $ctrl.dataHandlers.processData(currencies, {
        ctrlDataName: 'currencies',
        transformBooleans: false
    });

    $ctrl.dataHandlers.processData(accruals, {
        ctrlDataName: 'accruals',
        transformBooleans: false
    });

    $ctrl.dataHandlers.processData(earnings, {
        ctrlDataName: 'earnings',
        transformBooleans: false
    });

    $ctrl.dataHandlers.processData(benefits, {
        ctrlDataName: 'benefits',
        transformBooleans: false
    });

    $ctrl.dataHandlers.processData(companies, {
        mapToLabelValue: 'companyMap',
        entityList: companies,
        mapLabelKey: 'LegalName',
        mapValueKey: 'Id'
    });

    $ctrl.payrollRunReview = payrollRunReview;
    if (!modifiedPayrollRunReview) {
        $ctrl.warnings = payrollRunReview.PayrollRunReview.Warnings;
        $ctrl.hasModifiedPayrollRunReview = false;
    } else $ctrl.hasRecentlyRecalculated = true;

    $ctrl.processPayrollRunReview();

    if (!$ctrl.globalSelectedCompany.companyMap.length > 0) $ctrl.globalSelectedCompany.companyMap = $ctrl.companyMap.map(obj => ({ ...obj }));

    const payPeriod = payrollRunReview.PayrollRunReview.PayrollRun.PayPeriod;
    const paySchedule = payPeriod.PaySchedule;
    const company = payPeriod.Company ?? paySchedule.Company;
    const companyId = company?.Id;
    const companyLegalName = company?.LegalName;

    if (companyId && companyLegalName && companyId !== $ctrl.globalSelectedCompany.companyId) {
        $ctrl.utils.toast(`Switching Payroll Run's Company (${companyLegalName})`, "INFO");
        $ctrl.globalSelectedCompany.setCompany(companyId, companyLegalName);
    }

    $ctrl.globalSelectedCompany.setMenuItems();
    $ctrl.globalSelectedCompany.clearCompanyMenuItems();

    if ($ctrl.tempStoredEntityId) {
        const tempStoredEntity = $ctrl.payrollRunReview.PayrollRunReview.Workers.find(worker => worker.Id === $ctrl.tempStoredEntityId);
        if ($ctrl.storedTab === 4) $ctrl.setSelectedEntity(tempStoredEntity);
        else if ($ctrl.storedTab === 5) $ctrl.setPaySlip(tempStoredEntity.PaySlipPreview);

        $ctrl.tempStoredEntityId = null;
        tempStoredEntity = null;
    }

    $ctrl.encashAccrualBalances = $ctrl.payrollRunReviewService.getCachedJobs($ctrl.pageParameters.id)[$ctrl.pageParameters.jobId]?.encashAccrualBalances;
    $ctrl.isGettingEntities = false;
}, 500)).catch(error => {
    $ctrl.entityUiStateService.initializationError = error.data?.message || "Failed to load required data.";
    $ctrl.utils.toast($ctrl.entityUiStateService.initializationError, "ERROR");
    console.error("Data loading failed:", error);

    if (isDev || isProd) {
        $ctrl.$state.go("payroll_processing");
    }
}).finally(() => $ctrl.isGettingEntities = false);

$ctrl.isUpdating = true;

$ctrl.sendData(
    "lonti_app_payroll_service_attendance_summary_UpdateAttendanceSummary",
    $ctrl.form,
    $ctrl.selectedEntity.EarningCode,
    "PUT"
);

for (let prop in form) {
    if (form.hasOwnProperty(prop)) {
        form[prop] = undefined;
    }
}

if ($ctrl.isEditingAttendance) {
    $ctrl.setIsEditing();
    return;
} else {
    delete $ctrl.selectedEntity;
    delete $ctrl.selectedEntityName;
    delete $ctrl.selectedEntityDetails;
}

$ctrl.resetForm($ctrl.form);

if ($ctrl.isEditingAttendance) $ctrl.resetForm($ctrl.form);

$ctrl.isEditingAttendance = !$ctrl.isEditingAttendance;

if ($ctrl.isEditingAttendance) $ctrl.setInputValues();

if ($ctrl.selectedEntity === undefined) return;
if (Object.keys($ctrl.selectedEntity).length === 0) return;

useExistingValuesAsInputValues($ctrl.form);

function useExistingValuesAsInputValues(form) {
    const obj = $ctrl.selectedEntity;

    for (let key in form) {
        const adjustedKey = key.charAt(0).toUpperCase() + key.slice(1);


        form[key] = obj.hasOwnProperty(adjustedKey) ? obj[adjustedKey] : undefined;
    }
}

const payrollRunObj = $ctrl.payrollRunReview.PayrollRunReview.PayrollRun;
const payrollRun = Object.entries(payrollRunObj);

const payPeriodObj = payrollRunObj.PayPeriod;
const payScheduleObj = payPeriodObj.PaySchedule;

$ctrl.rightColumn = payrollRun.filter(row =>
    !["Id", "DisplayName", "PostingDate", "ProcessDate", "PayPeriod", "Status", "RunType", "TotalEmployees", "Description", "OffCycleReason"].includes(row[0])
);

let ctr = 0;
$ctrl.rightColumn.forEach(([key, value]) => {
    if (key.includes("Total")) $ctrl.rightColumn[ctr][1] = value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    ctr++;
})

$ctrl.rightColumn.unshift(["Section", "Calculation Preview"])

$ctrl.leftColumn = [
    ["Section", "Summary"],
    ["RunType", payrollRunObj.RunType],
    ["PaySchedule", payScheduleObj.DisplayName],
    ["PayPeriod", $ctrl.parseDate(payPeriodObj.StartDate).split(" ")[0] + " - " + $ctrl.parseDate(payPeriodObj.EndDate).split(" ")[0]],
    payrollRunObj.ProcessDate && ["ProcessDate", $ctrl.utils.parseDate(payrollRunObj.ProcessDate)],
    ["PostingDate", $ctrl.utils.parseDate(payrollRunObj.PostingDate)],
    ["TotalEmployees", payrollRunObj.TotalEmployees],
];

if (payrollRunObj.Description) $ctrl.leftColumn.push(["Description", payrollRunObj.Description]);
if (payrollRunObj.OffCycleReason) $ctrl.leftColumn.push(["OffCycleReason", payrollRunObj.OffCycleReason]);

$ctrl.leftColumn = formatKeysForDisplay($ctrl.leftColumn.filter(arr => arr !== undefined));
$ctrl.rightColumn = formatKeysForDisplay($ctrl.rightColumn);

$ctrl.dataHandlers.processData($ctrl.payrollRunReview.PayrollRunReview.Workers, {
    ctrlDataName: 'workers',
    hideColumns: true,
    transformBooleans: false
});

$ctrl.payrollAppApi.lonti_app_payroll_service_payroll_run_SelectPayrollRun(
    {
        id: $ctrl.pageParameters.id
    },
    { headers: $ctrl.authCookies.setHeaders() }
).then(result => {
    payrollRunObj.Status = result.data.payrollrun.Status;
});

$ctrl.setSection($ctrl.storedTab);
$ctrl.setTable();

function formatKeysForDisplay(arr) {
    return arr.map(([key, value]) => {
        const transformedKey = key.replace(/([A-Z])/g, ' $1').trim();
        return [transformedKey, value];
    });
}

// Reset
$ctrl.selectedEntity = null;
$ctrl.selectedEntityName = null;
$ctrl.selectedEntityDetails = null;

$ctrl.currentPage = 1;

$ctrl.tableData = $ctrl.workers;
$ctrl.transformEmploymentStartDateForDisplay();
$ctrl.filteredTableData = $ctrl.tableData;

$ctrl.filteredTableData = $ctrl.tableData.filter((row) =>
    Object.values(row).some((value) =>  
        String(value)
            .toLowerCase()
            .includes($ctrl.filterTarget.toLowerCase()))
);

$ctrl.$modal.open("confirm-action-modal", {
    title: $ctrl.hasModifiedPayrollRunReview ? "Generate Payslips with Pay Component Overrides?" : "Generate Payslips?",
    body: "Once generated, Payslips can no longer be modified or regenerated for this Payroll Run. Proceed?" + ($ctrl.hasModifiedPayrollRunReview ? " This Payroll Run has Pay Component Overrides and will use those values instead. Proceed?" : "")
}).then(res => {
    if (res.result === "ok") {
        $ctrl.selectedEntity = null;
        $ctrl.selectedEntityName = null;
        $ctrl.selectedEntityDetails = "";

        $ctrl.selectedPayslip = null;
        $ctrl.selectedPayslipName = null;
        $ctrl.selectedPayslipDetails = null;

        $ctrl.isGettingEntities = true;

        $ctrl.payrollAppApi.lonti_app_payroll_service_payroll_run_ProcessPayroll(
            {
                id: $ctrl.pageParameters.id,
                encashAccrualBalances: $ctrl.encashAccrualBalances,
                jobId: $ctrl.pageParameters.jobId
            },
            $ctrl.hasModifiedPayrollRunReview ? $ctrl.payrollRunReview.PayrollRunReview.Workers.map(worker => {
                return {
                    WorkerId: worker.Id,
                    Earnings: worker.Earnings.map(earning => {
                        return {
                            Id: earning.Id,
                            CustomAmount: earning.CustomAmount
                        }
                    }),
                    Benefits: worker.Benefits.map(benefit => {
                        return {
                            Id: benefit.Id,
                            CustomEmployeeAmount: benefit.CustomEmployeeAmount,
                            CustomEmployerAmount: benefit.CustomEmployerAmount
                        }
                    })
                }
            })
                : undefined
            , { headers: $ctrl.authCookies.setHeaders() })
            .then(result => {
                if (result.data.result === "OK") {
                    if (window.location.hash === "#!/review_payroll") $ctrl.$state.go("payroll_report", { id: $ctrl.pageParameters.id, origin: $ctrl.pageParameters.origin });
                    else $ctrl.utils.toast("Successfully ran " + $ctrl.payrollRunReview.PayrollRunReview.PayrollRun.DisplayName, "INFO");
                }
            })
            .catch(reason => {
                $ctrl.utils.toast(reason.data.message, reason.data.result);
                $ctrl.isGettingEntities = false;
            });

        $ctrl.$state.go("payroll_processing");
        $ctrl.utils.toast($ctrl.payrollRunReview.PayrollRunReview.PayrollRun.DisplayName + " is now processing. We will notify you when it is finished.", "INFO");
    }
})

const taxScheduleData = taxSchedules.map(({Id, EffectiveFromDate, ...taxSchedCols}) => taxSchedCols);

await $ctrl.$modal.open("view-tax-schedules-modal", {
    props:
    {
        TaxSchedules: taxScheduleData
    }
});

// Main
if (!row) {
    resetselectedPayslip();
    clearDetailsElement();
    return;
}

$ctrl.selectedPayslip = row;
$ctrl.selectedPayslipDetails = "";

populateEntityDetails(row);
injectDetailsIntoElement();
setEntityName(row);

function resetselectedPayslip() {
    $ctrl.selectedPayslip = null;
    $ctrl.selectedPayslipName = null;
    $ctrl.selectedPayslipDetails = "";
}

function clearDetailsElement() {
    const detailsElement = document.getElementById("details");
    if (detailsElement) detailsElement.innerHTML = "";
}

// Helper Functions
function setEntityName(row) {
    $ctrl.selectedPayslipName = row.PayPeriodDisplayName;
}

function populateEntityDetails(row) {
    for (const [key, value] of Object.entries(row)) {
        if (key.startsWith("$$") || (isExcludedKey(key, value) && key !== "PayPeriodRate")) continue;
        switch (key) {
            case "PayPeriodRate":
                appendPayPeriodRate(row.Frequency, value);
                break;
            case "WorkerName":
                appendWorkerName(value);
                break;
            case "BankInfo":
                Object.entries(value).forEach(([key, value]) => key !== "Id" ? appendGeneralDetails(key, value) : undefined);
                break;
            case "CreatedDate":
                return; // Stop processing at CreatedDate
            case "AccrualBalance":
                if (value.length > 0) {
                    $ctrl.selectedPayslipDetails += appendSectionTitle("Leave Credits");
                    appendAccrualBalances(value);
                }
                break;
            case "GrossPay":
            case "TotalDeductions":
            case "NetPay":
                appendTotals(key, value);
                break;
            default:
                if (isStatutoryCompliance(key)) {
                    appendStatutoryCompliance(value);
                } else if (isPayComponent(key)) {
                    appendPayComponents(key, value, row);
                } else {
                    appendGeneralDetails(key, value);
                }
        }
    }
}

function injectDetailsIntoElement() {
    const element = document.getElementById("details");
    if (element) {
        element.innerHTML = $ctrl.selectedPayslipDetails;
    } else {
        $ctrl.$timeout(injectDetailsIntoElement, 100);
    }
}

// Utility Functions
function isExcludedKey(key, value) {
    const excludedKeys = [
        "Id", "PayPeriod", "Payroll", "Department", "Position",
        "Frequency", "GrossTaxable", "GrossNonTaxable", "PreTaxDeductions", "NetTaxable", "Taxes",
        "PostTaxDeductions", "Ytd"
    ];
