function processAssignment() {
  $ctrl.isAssigning = true;

  const selectedPayComponent = $ctrl.selectedPayComponent;
  const selectedPayComponentClass = selectedPayComponent.Classification;
  const isEarning = selectedPayComponentClass === "Earnings";
  const workers = $ctrl.payrollRunReview.PayrollRunReview.Workers;

  $ctrl.assignedToWorkers.forEach(assignedWorker => {
    const relatedWorker = workers.find(worker => worker.Id === assignedWorker.Id);
    if (!relatedWorker) return;

    const relatedPayComponent = relatedWorker[selectedPayComponentClass].find(payComponent => payComponent.Id === selectedPayComponent.Id);

    if (relatedPayComponent) { // Handle modifications to existing components
      let hasChanges = false;

      if (isEarning) {
        if (relatedPayComponent.CustomAmount !== assignedWorker.CustomEmployeeAmount) {
          relatedPayComponent.CustomAmount = assignedWorker.CustomEmployeeAmount;
          hasChanges = true;
        }
      } else {
        if (relatedPayComponent.CustomEmployeeAmount !== assignedWorker.CustomEmployeeAmount || relatedPayComponent.CustomEmployerAmount !== assignedWorker.CustomEmployerAmount) {
          relatedPayComponent.CustomEmployeeAmount = assignedWorker.CustomEmployeeAmount;
          relatedPayComponent.CustomEmployerAmount = assignedWorker.CustomEmployerAmount;
          hasChanges = true;
        }
      }

      // Only override the Origin to "WORKER" if amounts were modified
      if (hasChanges) {
        relatedPayComponent.Origin = "WORKER";
      }

    } else { // Handle new components to add
      const payComponentToAdd = { ...selectedPayComponent };

      if (isEarning) {
        payComponentToAdd.CustomAmount = assignedWorker.CustomEmployeeAmount;
      } else {
        payComponentToAdd.CustomEmployeeAmount = assignedWorker.CustomEmployeeAmount;
        payComponentToAdd.CustomEmployerAmount = assignedWorker.CustomEmployerAmount;
      }

      // Set Origin to "WORKER" since it is newly added via overrides
      payComponentToAdd.Origin = "WORKER";
      relatedWorker[selectedPayComponentClass].push(transformPayComponent(payComponentToAdd));
    }
  });

  // Handle components to remove
  $ctrl.originalAssignedToWorkers
    .filter(originalAssignedWorker => !$ctrl.assignedToWorkers
      .some(assignedWorker => assignedWorker.Id === originalAssignedWorker.Id))
    .forEach(workerToUnassign => {
      const relatedWorker = workers.find(worker => worker.Id === workerToUnassign.Id);
      const relatedPayComponentIndex = relatedWorker[selectedPayComponentClass].findIndex(payComponent => payComponent.Id === selectedPayComponent.Id);
      if (relatedPayComponentIndex != -1) relatedWorker[selectedPayComponentClass].splice(relatedPayComponentIndex, 1);
    });

  $ctrl.$notificationManager.show("Assignment Processed", {
    delay: 3500,
    icon: 'check',
    color: 'success',
    dismissible: true,
    animation: 'fade'
  });

  $ctrl.$timeout(() => {
    $ctrl.isAssigning = false;
    $ctrl.hasRecentlyRecalculated = false;
    $ctrl.hasModifiedPayrollRunReview = true;
  }, 100);

  function transformPayComponent(selectedPayComponent) {
    if (typeof selectedPayComponent !== 'object' || selectedPayComponent === null) {
      return selectedPayComponent;
    }

    const payComponentToAdd = {};
    for (const key in selectedPayComponent) {
      if (Object.prototype.hasOwnProperty.call(selectedPayComponent, key)) {
        if (key.toLowerCase().includes('calculationmethod')) {
          let newKey = key.replace(/Id$/i, '');
          payComponentToAdd[newKey] = { Id: selectedPayComponent[key] };
          delete payComponentToAdd[key];
        } else {
          payComponentToAdd[key] = transformPayComponent(selectedPayComponent[key]);
        }
      }
    }
    return payComponentToAdd;
  }
}

