function fetchExcel(formData) {
  const params = new URLSearchParams(formData);
  params.set("jobId", $ctrl.pageParameters.jobId);
  fetch(`${endpoint}?${params.toString()}`, {
    method: "POST",
    headers: {
      ...$ctrl.authCookies.setHeaders(),
      "Content-Type": "application/json;charset=UTF-8"
    },
    body: $ctrl.hasModifiedPayrollRunReview ?
    JSON.stringify($ctrl.payrollRunReview.PayrollRunReview.Workers.map(worker => {
      return {
        WorkerId: worker.Id,
        Earnings: worker.Earnings.map(earning => {
          return {
            Id: earning.Id,
            CustomAmount: earning.CustomAmount
          }
      }),
        Benefits: worker.Benefits.map(benefit => {
          return {
            Id: benefit.Id,
            CustomEmployeeAmount: benefit.CustomEmployeeAmount,
            CustomEmployerAmount: benefit.CustomEmployerAmount
          }
        })
      }
    }))
      : JSON.stringify({})
  }).then(response => {
    if (response.status === 200) {
      return response.blob();
    }
    throw new Error('Failed to fetch file');
  })
    .then(blob => {
      const payPeriod = $ctrl.payrollRunReview.PayrollRunReview.PayrollRun.PayPeriod;
      const payPeriodStartDate = $ctrl.parseDate(payPeriod.StartDate).split("-");
      const payPeriodEndDate = $ctrl.parseDate(payPeriod.EndDate).split("-");

      const payPeriodStartYear = payPeriodStartDate[0];
      const payPeriodStartMonth = payPeriodStartDate[1];
      const payPeriodStartDay = payPeriodStartDate[2].split(" ")[0];

      const payPeriodEndYear = payPeriodEndDate[0];
      const payPeriodEndMonth = payPeriodEndDate[1];
      const payPeriodEndDay = payPeriodEndDate[2].split(" ")[0];

      const dateRange = (payPeriodStartYear !== payPeriodEndYear)
        ? payPeriodStartMonth + "_" + payPeriodStartDay + "_" + payPeriodStartYear + "-" + payPeriodEndMonth + "_" + payPeriodEndDay + "_" + payPeriodEndYear
        : (payPeriodStartMonth !== payPeriodEndMonth)
          ? payPeriodStartMonth + "_" + payPeriodStartDay + "-" + payPeriodEndMonth + "_" + payPeriodEndDay + "_" + payPeriodEndYear
          : payPeriodStartMonth + "_" + payPeriodStartDay + "-" + payPeriodEndDay + "_" + payPeriodEndYear;

      const fileName = "PREVIEW_" + dateRange + "." + $ctrl.globalSelectedCompany.companyName.replaceAll(" ", "") + ".Report_PREVIEW.xlsx";

      const link = document.createElement('a');
      const url = window.URL.createObjectURL(blob);

      link.href = url;
      link.download = fileName;
      link.click();
      window.URL.revokeObjectURL(url);
    })
    .catch(error => $ctrl.utils.toast(error, error))
    .finally(() => $ctrl.$timeout(() => $ctrl.isExportingReport = false), 500);
}

