const payrollRunId = $ctrl.pageParameters.id;
const displayName = $ctrl.payrollRunReview.PayrollRunReview.PayrollRun.DisplayName;
let encashAccrualBalances = false;
let requestBody;

const confirmAccrualBalanceEncashmentResponse = await this.$modal.open("confirm-action-modal", {
    title: $ctrl.en.global.notifications.payrollRun.initiateReview.confirm.title,
    body: $ctrl.en.global.notifications.payrollRun.initiateReview.confirm.body,
    confirmButtonLabel: "Yes",
    cancelButtonLabel: "No"
}).then(res => {
    return res.result;
});

if (["ok", "cancel"].includes(confirmAccrualBalanceEncashmentResponse)) encashAccrualBalances = confirmAccrualBalanceEncashmentResponse === "ok" ? true : false;
else return;

try {
    const requestParameters = {
        id: payrollRunId,
        maskSensitiveWorkerInfo: false,
        encashAccrualBalances: encashAccrualBalances
    };

    const requestHeaders = {
        headers: $ctrl.authCookies.setHeaders()
    };

    if ($ctrl.hasModifiedPayrollRunReview) {
        requestBody = $ctrl.payrollRunReview.PayrollRunReview.Workers.map(worker => {
            return {
                WorkerId: worker.Id,
                Earnings: worker.Earnings.map(earning => {
                    return {
                        Id: earning.Id,
                        CustomAmount: earning.CustomAmount,
                        Origin: earning.Origin
                    }
                }),
                Benefits: worker.Benefits.map(benefit => {
                    return {
                        Id: benefit.Id,
                        CustomEmployeeAmount: benefit.CustomEmployeeAmount,
                        CustomEmployerAmount: benefit.CustomEmployerAmount,
                        Origin: benefit.Origin
                    }
                })
            }
        });
    }

    const response = await $ctrl.payrollAppApi.lonti_app_payroll_service_payroll_run_InitiateReviewPayrollRun(
        requestParameters,
        requestBody,
        requestHeaders
    );

    const reviewPayrollRunJobData = response?.data?.PayrollRunReviewJob;

    if (!reviewPayrollRunJobData) {
        throw new Error($ctrl.en.global.notifications.payrollRun.initiateReview.error.console.UNEXPECTED_JOB_DATA);
    }

    reviewPayrollRunJobData.encashAccrualBalances = encashAccrualBalances;

    $ctrl.payrollRunReviewService.cacheJobDetails(
        payrollRunId,
        reviewPayrollRunJobData
    );

    $ctrl.utils.toast(
        $ctrl.en.global.notifications.payrollRun.initiateReview.info.INITIATE(displayName),
        "INFO"
    );

    $ctrl.pollingService.payrollRunReview.startPolling(payrollRunId);
    $ctrl.$state.go("payroll_processing");
} catch (error) {
    console.error($ctrl.en.global.notifications.payrollRun.initiateReview.error.console.FAILED(displayName), error);
    $ctrl.utils.toast(
        $ctrl.en.global.notifications.payrollRun.initiateReview.error.toast.FAILED(displayName),
        "ERROR"
    );
}

$ctrl.tableData.forEach(row => {
    const employmentStartDate = row.EmploymentInfo.EmploymentStartDate;
    const date = new Date(employmentStartDate);

    if (!(date instanceof Date) || isNaN(date.getTime())) {
        return;
    }

    const year = date.getFullYear();
    const month = (date.getMonth() + 1).toString().padStart(2, '0');
    const day = date.getDate().toString().padStart(2, '0');

    row.EmploymentInfo.EmploymentStartDate = `${year}-${month}-${day}`;
});

const tabs = new Map([
    [1, [$ctrl.payComponents.workerEarnings, $ctrl.payComponents.workerBenefits]],
    [2, [$ctrl.payComponents.positionEarnings, $ctrl.payComponents.positionBenefits]],
    [3, $ctrl.payComponents.taxes],
    [4, $ctrl.workerAccrualBalances]
]);

$ctrl.displayedPayComponents = tabs.get(selectedTab);
